public static class Practice {
 public static void Apply(PracticeState s, string action, int value) {
  if(action=="enter"){s.Active=true;s.Subscriptions=1;s.InputEnabled=!s.Paused;}
  else if(action=="exit"){s.Active=false;s.InputEnabled=false;s.Subscriptions=0;s.LiveObjects=0;}
  else if(action=="pause"){s.Paused=true;s.InputEnabled=false;}
  else if(action=="resume"){s.Paused=false;s.InputEnabled=s.Active;}
  else if(action=="collect" && s.Active && s.InputEnabled){s.Score+=value;s.SavedScore=s.Score;}
  else if(action=="spawn" && s.Active){s.LiveObjects=1;}
  else if(action=="despawn"){s.LiveObjects=0;}
 }
}

public static class Practice {
 static bool Finite(float x){return !float.IsNaN(x)&&!float.IsInfinity(x);}
 public static bool CanPlace(float[] p,float radius,float[] other,float otherRadius,int dimensions,float clearance){
  if((dimensions!=2&&dimensions!=3)||p==null||other==null||p.Length<3||other.Length<3)return false;
  if(!Finite(radius)||!Finite(otherRadius)||!Finite(clearance)||radius<0||otherRadius<0||clearance<0)return false;
  for(int i=0;i<3;i++){if(i==1&&dimensions==2)continue;if(!Finite(p[i])||!Finite(other[i]))return false;}
  double x=(double)p[0]-other[0],z=(double)p[2]-other[2],y=dimensions==3?(double)p[1]-other[1]:0;
  double gap=(double)radius+otherRadius+clearance;
  return x*x+y*y+z*z>=gap*gap;
 }
}

public static class Practice { public static int[] Order(int[] parent){
 if(parent==null)return null;int n=parent.Length;var done=new bool[n];var result=new int[n];
 for(int i=0;i<n;i++)if(parent[i]<-1||parent[i]>=n||parent[i]==i)return null;
 for(int k=0;k<n;k++){int next=-1;for(int i=0;i<n;i++)if(!done[i]&&(parent[i]==-1||done[parent[i]])){next=i;break;}if(next<0)return null;result[k]=next;done[next]=true;}
 return result;
} }

public static class Practice { public static bool Commit(BatchState s,int[] indices,int price){
 if(s==null||s.Owned==null||s.Locked==null||s.Owned.Length!=s.Locked.Length||indices==null||indices.Length==0||price<0)return false;
 long total=(long)price*indices.Length;if(total>s.Gold)return false;
 var seen=new bool[s.Owned.Length];foreach(int i in indices){if(i<0||i>=seen.Length||seen[i]||s.Owned[i]||s.Locked[i])return false;seen[i]=true;}
 foreach(int i in indices)s.Owned[i]=true;s.Gold-=(int)total;return true;
} }

public static class Practice { public static bool Complete(Progress s,int node,int[] prerequisites,int reward){
 if(s==null||s.Done==null||prerequisites==null||node<0||node>=s.Done.Length||s.Done[node]||reward<0)return false;
 if((long)s.Currency+reward>int.MaxValue)return false;
 foreach(int p in prerequisites)if(p<0||p>=s.Done.Length||p==node||!s.Done[p])return false;
 s.Done[node]=true;s.Currency+=reward;return true;
} }
